rules.summary:
[{
  "if": "Patient does not meet DSM criteria for a mental disorder or sufficient impairment.",
  "then": "Do not submit treatment plan for insurance approval; treatment may not be covered."
},
{
  "if": "Diagnosing patient for treatment approval.",
  "then": "Use accurate, complete DSM diagnoses; do not exaggerate or falsify symptoms."
},
{
  "if": "Reporting progress for continued sessions.",
  "then": "Document specific improvement, ongoing symptoms/impairments, and rationale for continued treatment."
},
{
  "if": "Treatment goals are specified.",
  "then": "State goals in observable, measurable terms (countable behaviors, assessment scores, etc.)."
},
{
  "if": "Choosing interventions.",
  "then": "Select empirically supported techniques matched to symptom profile and documented goals."
},
{
  "if": "Patient expresses resistance, new stressors, or worsening symptoms.",
  "then": "Document these, update treatment plan as needed, and report rationale for any changes."
},
{
  "if": "Session notes are requested.",
  "then": "Include sufficient clinical data (symptoms, interventions, progress) but avoid unnecessary detail to protect privacy."
},
{
  "if": "Medication is not used.",
  "then": "Document rationale and patient education regarding medication options."
},
{
  "if": "Communicating with managed care reviewers by phone.",
  "then": "Remain courteous, professional, and prepare data as for written report."
},
{
  "if": "State law is more restrictive than HIPAA.",
  "then": "Follow state law and restrict information accordingly when submitting reports."
}
]

[
  {
    "if": "Patient reports a specific feared object or situation and associated avoidance or anxiety",
    "then": "Initiate assessment and construct a fear hierarchy using SUDs ratings, considering both imaginal and in vivo situations."
  },
  {
    "if": "Patient is unwilling or unable to engage in in vivo exposure immediately",
    "then": "Begin with imaginal exposure and/or cognitive restructuring to prepare for eventual in vivo exposure."
  },
  {
    "if": "Patient engages in avoidance, escape, or safety behaviors during exposure or daily life",
    "then": "Identify and explicitly block these behaviors, encourage abandonment during exposure tasks, and challenge beliefs about their necessity."
  },
  {
    "if": "Patient demonstrates catastrophic predictions or distorted automatic thoughts about feared situations",
    "then": "Elicit and challenge these thoughts through Socratic questioning, guided discovery, and provide psychoeducation as needed."
  },
  {
    "if": "Patient completes exposure with reduced anxiety or misappraisal",
    "then": "Praise and reinforce patient effort, encourage self-reward, and progress to next rung of fear hierarchy."
  },
  {
    "if": "Patient demonstrates high reliance on therapist or companions for exposure",
    "then": "Gradually phase out external supports to build self-efficacy and independence."
  },
  {
    "if": "Exposure session concludes without significant reduction in anxiety or misappraisal",
    "then": "Extend session, revert to less feared stimulus, troubleshoot safety behavior use, and adjust hierarchy or cognitive approach as needed."
  },
  {
    "if": "Patient does not complete homework or exposure assignments as planned",
    "then": "Clarify and specify homework instructions, break into achievable steps, role-play barriers, and review/discuss costs and benefits."
  },
  {
    "if": "Patient presents with comorbid psychiatric or substance use disorders",
    "then": "Assess and address comorbidities; refer as appropriate for counseling or detoxification before continuing exposure."
  }
]
